//! Contains entity ingestion models

use schemars::JsonSchema;
use std::{fmt::Display, str::FromStr};

// use std::str::FromStr;
//
use serde::Serialize;
use strum::{EnumIter, EnumString};
use thiserror::Error;
use uuid::Uuid;

use crate::domain::repositories::{
    entity_ingestion::EntitySearchPipelineError, parliament_api::ParliamentApiError,
};

/// Data required to search entities
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EntityIngestionRequest;

/// Key used for ingestion
#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
#[serde(transparent)]
pub struct IngestionKey(Uuid);

impl Display for IngestionKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.0.to_string().as_str())
    }
}

impl FromStr for IngestionKey {
    type Err = EntityIngestionError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let id =
            Uuid::from_str(s).map_err(|e| EntityIngestionError::InvalidStage(e.to_string()))?;
        Ok(Self(id))
    }
}

impl IngestionKey {
    /// Creates a new key
    #[must_use]
    pub const fn new(uuid: Uuid) -> Self {
        Self(uuid)
    }

    /// Underlying UUID
    #[must_use]
    pub const fn uuid(&self) -> Uuid {
        self.0
    }
}

impl Default for IngestionKey {
    fn default() -> Self {
        Self::new(Uuid::now_v7())
    }
}

/// From what stage to run in the Member pipeline
#[derive(Clone, Debug, PartialEq, Eq, EnumString, EnumIter, Serialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
#[allow(missing_docs)]
#[strum(ascii_case_insensitive)]
pub enum MemberIngestionStage {
    Fetch,
    Load,
}
/// Supported acquisition stage for declarations.
#[derive(Clone, Debug, PartialEq, Eq, EnumString, EnumIter, Serialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
#[strum(ascii_case_insensitive)]
pub enum DeclarationIngestionStage {
    /// Capture source evidence for later offline processing.
    Fetch,
    /// Split captured funding occurrences and funder observations offline.
    Clean,
    /// Resolve cleaned funder observations and attribute each occurrence.
    Resolve,
    /// Load the published identities and attributions into the database.
    Load,
}

/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntityIngestionError {
    /// Errors related to the parliament API
    #[error("error when retrieving data from the parliament API: {0}")]
    ApiError(#[from] ParliamentApiError),

    /// Generic error related to entity parsing, cleaning and resolution
    #[error("error in ingestion pipeline: {0}")]
    DataError(String),

    config: PathBuf,
    ingestion_key: Option<IngestionKey>,
) -> anyhow::Result<CliSuccess<StageAcknowledgement<MemberIngestionStage>>> {
    let stage = MemberIngestionStage::from_str(&stage)?;
    let ingestion_key = ingestion_key.unwrap_or_default();
    let data_dir = match stage {
        MemberIngestionStage::Fetch => {
            let config = FetcherConfig::try_from(&config)?;
            let api = ParliamentApiClient::new(config.batch_size)?;
            let fs = ExposedDataPipeline::new_with_ingestion_key(
                &config.data_dir,
                ingestion_key.clone(),
            )?;
            FetcherService::new(fs, api)
                .fetch_members(&EntityIngestionRequest {})
                .await?;
            config.data_dir
        }
        MemberIngestionStage::Load => {
            let config = LoaderConfig::try_from(&config)?;
            let data_config = DataConfig::from_env()?;
            let fs = ExposedDataPipeline::new_with_ingestion_key(
                &config.data_dir,
                ingestion_key.clone(),
            )?;
            let db = ExposedDatabase::new(&data_config.connection_string).await?;
            IngesterService::new(fs, db).load_members().await?;
            config.data_dir
        }
    };
    Ok(CliSuccess::new(StageAcknowledgement {
        path: std::path::absolute(data_dir)?
            .join(ingestion_key.to_string())
            .join("raw/members.parquet"),
        ingestion_key,
        stage,
    }))
}
use std::future::Future;

use schemars::{JsonSchema, Schema, generate::SchemaSettings};
use serde::Serialize;
use strum::IntoEnumIterator;

use super::{CliSuccess, response::ErrorResponse};
use crate::domain::models::entity_ingestion::DeclarationIngestionStage;

fn schema<T: JsonSchema>() -> Schema {
    SchemaSettings::draft2020_12()
        .for_serialize()
        .into_generator()
        .into_root_schema_for::<T>()
}

trait ResponseSchema {
    fn schema() -> Schema;
}

impl<T: Serialize + JsonSchema, E> ResponseSchema for Result<CliSuccess<T>, E> {
    fn schema() -> Schema {
        schema::<T>()
    }
}

pub(super) trait HandlerSchema<Args> {
    fn response_schema(self) -> Schema;
}

macro_rules! handler_schema {
    ($($arg:ident),*) => {
        impl<F, Fut, $($arg,)*> HandlerSchema<($($arg,)*)> for F
        where
            F: FnOnce($($arg),*) -> Fut,
            Fut: Future,
            Fut::Output: ResponseSchema,
        {
            fn response_schema(self) -> Schema {
                <Fut::Output as ResponseSchema>::schema()
            }
        }
    };
}

handler_schema!();
handler_schema!(A);
handler_schema!(A, B);
handler_schema!(A, B, C);

fn section(label: &str, schema: &Schema) -> String {
    format!(
        "{label}\n{}\n",
        serde_json::to_string_pretty(schema).expect("JSON schema serializes")
    )
}

fn failure() -> String {
    format!(
        "Success: one JSON document on stdout, exit 0.\nCommand failure: one JSON document on stderr, exit 1.\nClap argument errors and help use Clap's text output.\nSchemas use JSON Schema draft 2020-12.\n\n{}",
        section("Failure JSON schema:", &schema::<ErrorResponse>())
    )
}

pub(super) fn single<Args>(handler: impl HandlerSchema<Args>) -> String {
    format!(
        "{}\n{}",
        section("Success JSON schema:", &handler.response_schema()),
        failure()
    )
}

pub(super) fn declarations() -> String {
    let mut help = String::new();
    for stage in DeclarationIngestionStage::iter() {
        let mut schema = match stage {
            DeclarationIngestionStage::Fetch => super::fetch_declarations.response_schema(),
            DeclarationIngestionStage::Clean => super::clean_declarations.response_schema(),
            DeclarationIngestionStage::Resolve => super::resolve_declarations.response_schema(),
            DeclarationIngestionStage::Load => super::load_declarations.response_schema(),
        };
        if stage == DeclarationIngestionStage::Fetch {
            schema
                .as_object_mut()
                .expect("response schema is an object")["properties"]["stage"]["const"] =
                serde_json::to_value(&stage).expect("stage serializes");
        }
        let label = serde_json::to_value(&stage).expect("stage serializes");
        help.push_str(&section(
            &format!(
                "Success JSON schema ({}):",
                label.as_str().expect("stage is a string")
            ),
            &schema,
        ));
        help.push('\n');
    }
    help.push_str(&failure());
    help
}

